#!/bin/bash
# Pack every basketball take of EgoExo4D participant 415, plus each take's fisheye
# calibration. Generated by tools/gen_tar_expert.py; see the other
# tar_expert*.sh for the conventions.
#
# WHO THIS IS. Late Expert, gender not recorded, sfu. 9 takes in sfu_basketball_03. Shares a capture with 412, 413, 414, so that calibration covers several people.
#
# 9 takes, 4.3 minutes. Take indices: 20, 21, 23, 44, 46, 47, 68, 70, 72.
# Capture(s): sfu_basketball_03.
#
# CAMERAS, every take: cam01,cam02,cam03,cam04.
# The camera set is a property of the CAPTURE, not the university, and
# scripts/recon_common.sh reads each take's list off disk -- but check it
# matches before masking, and never copy an ALL_CAMS value between captures.
#
# The pipeline camera is resolved from the take's own best_exo now, so no
# manifest row is needed for it. Confirm against the stage-1 mask overlay
# before committing a capture to a view.
#
# WHAT EACH TAKE CONTRIBUTES:
#   frame_aligned_videos/cam0N.mp4         the 4K exo views
#   frame_aligned_videos/downscaled/448    the pipeline-resolution copies (dir)
#   trajectory/gopro_calibs.csv            per-take fisheye calibration
#
# Verify availability on the mirror BEFORE running this:
#
#   python3 -c "import json,os; R='/vision/group/egoexo4d/takes'; T=json.load(open('/vision/group/egoexo4d/takes.json')); [print('%-34s cams=%d 448=%d calib=%s' % (t['take_name'], sum(os.path.isfile('%s/%s/frame_aligned_videos/%s.mp4'%(R,t['take_name'],c)) for c in sorted(k for k in (t.get('frame_aligned_videos') or {}) if k.startswith('cam'))), len(os.listdir('%s/%s/frame_aligned_videos/downscaled/448'%(R,t['take_name']))) if os.path.isdir('%s/%s/frame_aligned_videos/downscaled/448'%(R,t['take_name'])) else 0, os.path.isfile('%s/%s/trajectory/gopro_calibs.csv'%(R,t['take_name'])))) for t in sorted(T,key=lambda x:x['take_idx']) if t.get('participant_uid')==415]"
#
#   bash scripts/tar_expert415.sh                    # -> <repo>/expert415_takes.tar
#   OUT=/scratch/expert415.tar bash scripts/tar_expert415.sh
#
# The archive is roughly 1.7 GB. Run it detached -- the -v output floods a
# terminal and a Ctrl-C leaves a truncated archive with no resume:
#   nohup bash scripts/tar_expert415.sh > tar415.log 2>&1 &

set -euo pipefail

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

TAKES_ROOT="${TAKES_ROOT:-/vision/group/egoexo4d/takes}"
OUT="${OUT:-$REPO/expert415_takes.tar}"

[ -d "$TAKES_ROOT" ] || { echo "ERROR: no takes root at $TAKES_ROOT" >&2; exit 1; }
mkdir -p "$(dirname "$OUT")"

# Checked before a byte is written. Filling a quota mid-tar leaves a truncated
# archive that looks finished, which is a worse failure than refusing to start.
NEED_KB=3319449
AVAIL_KB=$(df -Pk "$(dirname "$OUT")" | awk 'NR==2 {print $4}')
if [ "$AVAIL_KB" -lt "$NEED_KB" ]; then
    echo "ERROR: need ~$((NEED_KB / 1024 / 1024)) GB at $(dirname "$OUT"), have $((AVAIL_KB / 1024 / 1024)) GB" >&2
    echo "       set OUT to somewhere with room" >&2
    exit 1
fi

cd "$TAKES_ROOT"

# -c create, -h follow symlinks, -v so the log shows every file, -f the
# archive. No -z: the payload is already-encoded H.264.
tar -chvf "$OUT" \
    sfu_basketball_03_20/frame_aligned_videos/cam01.mp4 \
    sfu_basketball_03_20/frame_aligned_videos/cam02.mp4 \
    sfu_basketball_03_20/frame_aligned_videos/cam03.mp4 \
    sfu_basketball_03_20/frame_aligned_videos/cam04.mp4 \
    sfu_basketball_03_20/frame_aligned_videos/downscaled/448 \
    sfu_basketball_03_20/trajectory/gopro_calibs.csv \
    sfu_basketball_03_21/frame_aligned_videos/cam01.mp4 \
    sfu_basketball_03_21/frame_aligned_videos/cam02.mp4 \
    sfu_basketball_03_21/frame_aligned_videos/cam03.mp4 \
    sfu_basketball_03_21/frame_aligned_videos/cam04.mp4 \
    sfu_basketball_03_21/frame_aligned_videos/downscaled/448 \
    sfu_basketball_03_21/trajectory/gopro_calibs.csv \
    sfu_basketball_03_23/frame_aligned_videos/cam01.mp4 \
    sfu_basketball_03_23/frame_aligned_videos/cam02.mp4 \
    sfu_basketball_03_23/frame_aligned_videos/cam03.mp4 \
    sfu_basketball_03_23/frame_aligned_videos/cam04.mp4 \
    sfu_basketball_03_23/frame_aligned_videos/downscaled/448 \
    sfu_basketball_03_23/trajectory/gopro_calibs.csv \
    sfu_basketball_03_44/frame_aligned_videos/cam01.mp4 \
    sfu_basketball_03_44/frame_aligned_videos/cam02.mp4 \
    sfu_basketball_03_44/frame_aligned_videos/cam03.mp4 \
    sfu_basketball_03_44/frame_aligned_videos/cam04.mp4 \
    sfu_basketball_03_44/frame_aligned_videos/downscaled/448 \
    sfu_basketball_03_44/trajectory/gopro_calibs.csv \
    sfu_basketball_03_46/frame_aligned_videos/cam01.mp4 \
    sfu_basketball_03_46/frame_aligned_videos/cam02.mp4 \
    sfu_basketball_03_46/frame_aligned_videos/cam03.mp4 \
    sfu_basketball_03_46/frame_aligned_videos/cam04.mp4 \
    sfu_basketball_03_46/frame_aligned_videos/downscaled/448 \
    sfu_basketball_03_46/trajectory/gopro_calibs.csv \
    sfu_basketball_03_47/frame_aligned_videos/cam01.mp4 \
    sfu_basketball_03_47/frame_aligned_videos/cam02.mp4 \
    sfu_basketball_03_47/frame_aligned_videos/cam03.mp4 \
    sfu_basketball_03_47/frame_aligned_videos/cam04.mp4 \
    sfu_basketball_03_47/frame_aligned_videos/downscaled/448 \
    sfu_basketball_03_47/trajectory/gopro_calibs.csv \
    sfu_basketball_03_68/frame_aligned_videos/cam01.mp4 \
    sfu_basketball_03_68/frame_aligned_videos/cam02.mp4 \
    sfu_basketball_03_68/frame_aligned_videos/cam03.mp4 \
    sfu_basketball_03_68/frame_aligned_videos/cam04.mp4 \
    sfu_basketball_03_68/frame_aligned_videos/downscaled/448 \
    sfu_basketball_03_68/trajectory/gopro_calibs.csv \
    sfu_basketball_03_70/frame_aligned_videos/cam01.mp4 \
    sfu_basketball_03_70/frame_aligned_videos/cam02.mp4 \
    sfu_basketball_03_70/frame_aligned_videos/cam03.mp4 \
    sfu_basketball_03_70/frame_aligned_videos/cam04.mp4 \
    sfu_basketball_03_70/frame_aligned_videos/downscaled/448 \
    sfu_basketball_03_70/trajectory/gopro_calibs.csv \
    sfu_basketball_03_72/frame_aligned_videos/cam01.mp4 \
    sfu_basketball_03_72/frame_aligned_videos/cam02.mp4 \
    sfu_basketball_03_72/frame_aligned_videos/cam03.mp4 \
    sfu_basketball_03_72/frame_aligned_videos/cam04.mp4 \
    sfu_basketball_03_72/frame_aligned_videos/downscaled/448 \
    sfu_basketball_03_72/trajectory/gopro_calibs.csv

echo ""
echo "wrote $OUT  ($(du -h "$OUT" | cut -f1))"
echo "entries: $(tar -tf "$OUT" | wc -l)"
echo ""
echo "expected: 9 takes x (their cameras + the 448 dir record + its files + calib)"
echo ""
echo "extract on the other side with:"
echo "  tar -xf $(basename "$OUT") -C /their/egoexo4d/takes"
